545			<nav aria-label="Footer links">
546				<ul>
547					<li><a href="#top">Back to top</a></li>
548					<li><a href="https://github.com" target="_blank" rel="noopener noreferrer">GitHub<span class="visually-hidden"> (opens in new tab)</span></a></li>
549				</ul>
550			</nav>
551			<p><small>&copy; <span id="copyright-year">2026</span>. All rights reserved.</small></p>
552		</footer>
553		<script>
554			const copyrightYear = document.getElementById('copyright-year');
555			if (copyrightYear) {
556				copyrightYear.textContent = String(new Date().getFullYear());
557			}
558	
559			const messages = [
560				"This update was announced to screen readers!",
561				"Dynamic content updates work with aria-live regions.",
562				"Live regions are essential for accessible web apps.",
563				"Try this with a screen reader like NVDA or JAWS!"
564			];
565			let nextMessage = 0;
566			let count = 0;
567			const announceBtn = document.getElementById('announce');
568			const liveMessage = document.getElementById('live-message');
569			const contactForm = document.getElementById('contact-form');
570			const emailInput = document.getElementById('email');
571			const messageInput = document.getElementById('message');
572			const messageCount = document.getElementById('message-count');
573			const formStatus = document.getElementById('form-status');
574			const countDisplay = document.getElementById('count');
575			const countMessage = document.getElementById('count-message');
576			const decreaseBtn = document.getElementById('decrease');
577			const increaseBtn = document.getElementById('increase');
578			const resetBtn = document.getElementById('reset');
579	
580			const updateCountDisplay = () => {
581				countDisplay.textContent = count;
582				countMessage.textContent = `Count is now ${count}.`;
583			};
584	
585			if (countDisplay && countMessage) {
586				decreaseBtn?.addEventListener('click', () => {
587					count--;
588					updateCountDisplay();
589				});
590	
591				increaseBtn?.addEventListener('click', () => {
592					count++;
593					updateCountDisplay();
594				});
595	
596				resetBtn?.addEventListener('click', () => {
597					count = 0;
598					updateCountDisplay();
599				});
600			}
601	
602			if (announceBtn && liveMessage) {
603				announceBtn.addEventListener('click', () => {
604					liveMessage.textContent = messages[nextMessage];
605					nextMessage = (nextMessage + 1) % messages.length;
606				});
607			}
608	
609			if (contactForm) {
610				const emailError = document.getElementById('email-error');
611	
612				if (messageInput && messageCount) {
613					messageInput.addEventListener('input', () => {
614						const remaining = messageInput.maxLength - messageInput.value.length;
615						messageCount.textContent = remaining.toLocaleString();
616					});
617				}
618	
619				const validateEmail = () => {
620					let message = '';
621					if (emailInput.validity.valueMissing) {
622						message = 'Enter your email address.';
623					} else if (!emailInput.validity.valid) {
624						message = 'Enter an email address in the format name@example.com.';
625					}
626					emailError.textContent = message;
627					if (message) {
628						emailInput.setAttribute('aria-invalid', 'true');
629						emailInput.setAttribute('aria-describedby', 'email-error email-help');
630					} else {
631						emailInput.removeAttribute('aria-invalid');
632						emailInput.setAttribute('aria-describedby', 'email-help');
633					}
634					return !message;
635				};
